<template><div class="reviews"><header><h1>人工复核工作台</h1><div class="auth"><el-input v-model="token" type="password" show-password placeholder="管理令牌"/><el-input v-model="reviewer" placeholder="审核员名称"/><el-button type="primary" @click="connect">连接</el-button></div></header><el-alert v-if="error" type="error" :closable="false" :description="error"/><el-card v-if="connected"><template #header>提交复核</template><div class="form"><el-select v-model="policyId"><el-option v-for="p in policies" :key="p.id" :label="`${p.name} v${p.version}`" :value="p.id"/></el-select><el-input v-model="text" type="textarea" :rows="4"/><el-button type="primary" @click="create">检测并提交</el-button></div></el-card><el-card v-if="connected"><template #header>复核队列</template><article v-for="task in tasks" :key="task.id" class="row"><div><strong>{{ task.status }} · 风险 {{ task.risk_score }} · {{ task.recommended_action }}</strong><p>{{ task.text }}</p><small>{{ task.claimed_by||'未领取' }} · {{ task.conclusion||'待结论' }}</small></div><div class="actions"><el-button v-if="task.status==='pending'" @click="claim(task.id)">领取</el-button><el-button v-if="task.status==='claimed'&&task.claimed_by===reviewer" @click="release(task.id)">释放</el-button><el-button v-if="task.status==='claimed'&&task.claimed_by===reviewer" type="success" @click="resolve(task,'confirmed_violation')">确认违规</el-button><el-button v-if="task.status==='claimed'&&task.claimed_by===reviewer" @click="resolve(task,'false_positive')">误报</el-button><el-button v-if="task.status==='claimed'&&task.claimed_by===reviewer" type="warning" @click="resolve(task,'false_negative')">漏报</el-button></div></article><el-empty v-if="!tasks.length" description="暂无复核任务"/></el-card><el-card v-if="connected"><template #header>反馈候选</template><div v-for="item in candidates" :key="item.id" class="candidate"><el-tag>{{ item.type }}</el-tag><span>{{ item.value }}</span><small>{{ item.status }}</small></div></el-card></div></template>
<script setup>
import{ref}from'vue';import{claimReviewTask,createReviewTask,describeAPIError,fetchFeedbackCandidates,fetchPlatformPolicies,fetchReviewTasks,releaseReviewTask,resolveReviewTask}from'@/services/api';defineOptions({name:'HumanReviews'});const token=ref(sessionStorage.getItem('sensitive_admin_token')||''),reviewer=ref(sessionStorage.getItem('sensitive_reviewer')||''),connected=ref(false),error=ref(''),policies=ref([]),policyId=ref('default'),text=ref(''),tasks=ref([]),candidates=ref([]);const report=e=>error.value=describeAPIError(e).message;const refresh=async()=>{const[t,c]=await Promise.all([fetchReviewTasks(token.value),fetchFeedbackCandidates(token.value)]);tasks.value=t.items||[];candidates.value=c.items||[]};const connect=async()=>{sessionStorage.setItem('sensitive_admin_token',token.value);sessionStorage.setItem('sensitive_reviewer',reviewer.value);try{policies.value=(await fetchPlatformPolicies(token.value)).items||[];connected.value=true;await refresh()}catch(e){report(e)}};const create=async()=>{try{await createReviewTask(token.value,{policy_id:policyId.value,text:text.value});text.value='';await refresh()}catch(e){report(e)}};const claim=async id=>{try{await claimReviewTask(token.value,id,reviewer.value);await refresh()}catch(e){report(e)}};const release=async id=>{try{await releaseReviewTask(token.value,id,reviewer.value);await refresh()}catch(e){report(e)}};const resolve=async(task,conclusion)=>{const value=conclusion==='false_positive'?prompt('白名单候选短语',task.text):conclusion==='false_negative'?prompt('漏报词条',''):'';try{await resolveReviewTask(token.value,task.id,{reviewer:reviewer.value,conclusion,note:'控制台复核',candidate_type:conclusion==='false_positive'?'whitelist':conclusion==='false_negative'?'wordlist':'',value:value||''});await refresh()}catch(e){report(e)}}
</script><style scoped>.reviews{display:flex;flex-direction:column;gap:18px}.reviews header,.auth,.actions,.candidate{display:flex;align-items:center;justify-content:space-between;gap:10px}.auth{width:min(650px,100%)}.form{display:flex;flex-direction:column;gap:10px}.row{display:grid;grid-template-columns:1fr auto;gap:12px;padding:12px 0;border-bottom:1px solid var(--border-subtle)}.row p{white-space:pre-wrap}.row small,.candidate small{color:var(--text-sub)}.actions{flex-wrap:wrap}.candidate{justify-content:flex-start;padding:8px}@media(max-width:760px){.reviews header,.auth{flex-direction:column;align-items:stretch}.row{grid-template-columns:1fr}}</style>
